solution:
for sku, details in inventory.items():
    if details['stock'] < 10:
        print(f'LOW STOCK ALERT: {sku}')

    missing_tags = REQUIRED_TAGS - details['tags']
    if missing_tags:
        print(f'{sku} missing: {missing_tags}')

    all_inventory_tags = all_inventory_tags | details['tags']

print('All Tags:', all_inventory_tags)

